
(() => {
 const root=document.getElementById('cc-egg-review');
 const names=['Blossom Gardens','Azure Falls','Astral Crown'];
 const details=['garden ruins, pink canopies, contour trail','falls, cyan accents, grotto and fern sanctuary','pale summit, star garden and cosmic landmarks'];
 const routeImages=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
 const options={A:'Carry an intact egg home and hatch there; preserve the current extraction loop.',B:'Break the egg on the mountain, reveal the creature, then carry the creature home; discuss how this changes existing rules.',C:'Break or crack an outer shell on the mountain, carry the egg home, then hatch there.'};
 let selected=null;
 const colorProbe=document.createElement('span');colorProbe.hidden=true;root.appendChild(colorProbe);
 function resolvedColor(key){colorProbe.style.color='var('+key+')';return getComputedStyle(colorProbe).color;}
 function paint(canvas,p){
  const width=Math.max(180,canvas.getBoundingClientRect().width);const height=210;const dpr=window.devicePixelRatio||1;
  canvas.width=width*dpr;canvas.height=height*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);
  const color=resolvedColor;
  c.strokeStyle=color('--foreground');c.fillStyle=color('--foreground');c.lineWidth=2;
  const type=canvas.dataset.option;const start=32,end=width-38;const travel=Math.max(0,Math.min(1,(p-.3)/.45));const x=start+(end-start)*travel;
  c.globalAlpha=.35;c.beginPath();c.moveTo(12,166);c.lineTo(width-12,166);c.stroke();c.globalAlpha=1;
  c.beginPath();c.moveTo(end-17,142);c.lineTo(end-17,118);c.lineTo(end,102);c.lineTo(end+17,118);c.lineTo(end+17,142);c.closePath();c.stroke();
  c.font='12px sans-serif';c.textAlign='center';c.fillText('Nest',start,193);c.fillText('Home',end,193);
  c.beginPath();c.ellipse(start,160,19,5,0,0,Math.PI*2);c.stroke();
  c.beginPath();c.arc(x,120,7,0,Math.PI*2);c.fill();c.beginPath();c.moveTo(x,129);c.lineTo(x,148);c.moveTo(x,134);c.lineTo(x+15,139);c.moveTo(x,148);c.lineTo(x-7,163);c.moveTo(x,148);c.lineTo(x+7,163);c.stroke();
  const open=type==='B'?p>.2:p>.82;const ex=x+16,ey=132;
  if(!open){
   c.fillStyle=color('--viz-series-1');c.beginPath();c.ellipse(ex,ey,9,12,-.2,0,Math.PI*2);c.fill();
   c.strokeStyle=color('--foreground');if(type==='C'&&p>.17){c.beginPath();c.moveTo(ex-3,ey-9);c.lineTo(ex+2,ey-3);c.lineTo(ex-3,ey+2);c.lineTo(ex+3,ey+9);c.stroke();}
  }else{
   c.fillStyle=color('--viz-series-1');c.beginPath();c.ellipse(ex,ey+2,10,7,0,0,Math.PI*2);c.fill();
   c.beginPath();c.ellipse(ex-5,ey-7,3,9,-.3,0,Math.PI*2);c.ellipse(ex+3,ey-7,3,9,.15,0,Math.PI*2);c.fill();
   c.fillStyle=color('--foreground');c.beginPath();c.arc(ex+5,ey,1.5,0,Math.PI*2);c.fill();
   if(p<.9){c.globalAlpha=.5;c.beginPath();c.moveTo(ex-16,ey+12);c.lineTo(ex-11,ey+7);c.lineTo(ex-8,ey+14);c.moveTo(ex+12,ey+12);c.lineTo(ex+17,ey+5);c.lineTo(ex+21,ey+13);c.stroke();c.globalAlpha=1;}
  }
  c.fillStyle=color('--foreground');c.fillText(p<.2?(type==='A'?'Pick up':'Crack shell'):p<.75?'Escape':open?'Creature reveal':'Home hatch',width/2,36);
 }
 const runs=new Map();
 function replay(key){const canvas=root.querySelector('canvas[data-option="'+key+'"]');if(runs.has(key))cancelAnimationFrame(runs.get(key));
  if(matchMedia('(prefers-reduced-motion: reduce)').matches){paint(canvas,1);return;}
  const start=performance.now();function tick(t){const p=Math.min(1,(t-start)/3500);paint(canvas,p);if(p<1)runs.set(key,requestAnimationFrame(tick));else runs.delete(key);}runs.set(key,requestAnimationFrame(tick));
 }
 function applyState(s){if(s&&options[s.eggDirection]){selected=s.eggDirection;root.querySelector('#cc-choice').textContent='Selected '+selected+' · '+options[selected];}}
 applyState(window.openai?.widgetState?.modelContent);
 window.addEventListener('openai:set_globals',e=>applyState(e.detail?.globals?.widgetState?.modelContent));
 root.querySelectorAll('[data-replay]').forEach(b=>b.addEventListener('click',()=>replay(b.dataset.replay)));
 root.querySelectorAll('[data-pick]').forEach(b=>b.addEventListener('click',async()=>{selected=b.dataset.pick;root.querySelector('#cc-choice').textContent='Selected '+selected+' · '+options[selected];
  if(window.openai?.setWidgetState)window.openai.setWidgetState({modelContent:{eggDirection:selected},privateContent:null}).catch(()=>{});
  if(window.openai?.sendFollowUpMessage)await window.openai.sendFollowUpMessage({prompt:'For Climb & Collect egg-loop review, I choose option '+selected+': '+options[selected]+' Discuss the creature animation and art alternatives next with visual examples; record this as my direction without changing game code yet.',title:'Choose egg direction '+selected});
 }));
 root.querySelector('#cc-route-image').src=routeImages[0];
 const select=root.querySelector('#cc-kingdom');select.addEventListener('change',()=>{const i=Number(select.value);const img=root.querySelector('#cc-route-image');img.src=routeImages[i];img.alt='Existing '+names[i]+' mountain route, October 24';root.querySelector('#cc-route-detail').textContent=names[i]+' · '+details[i];});
 root.querySelector('#cc-review-route').addEventListener('click',async()=>{const i=Number(select.value);if(window.openai?.sendFollowUpMessage)await window.openai.sendFollowUpMessage({prompt:'Let us review the '+names[i]+' route in Climb & Collect next. Show its current route and visual alternatives, then ask one focused decision question in the popup. Do not rebuild it yet.',title:'Review '+names[i]});});
 const ro=new ResizeObserver(()=>root.querySelectorAll('canvas').forEach(c=>paint(c,0)));ro.observe(root);
 root.querySelectorAll('canvas').forEach(c=>paint(c,0));
})();
